CREATE COLUMN TABLE "TEST_AP"."OOST" ("Num" INTEGER CS_INT NOT NULL , "Descript" NVARCHAR(30), "StepId" SMALLINT CS_INT NOT NULL , "CloPrcnt" DECIMAL(21,6) CS_FIXED, "Canceled" NVARCHAR(1) DEFAULT 'N', "UserSign" SMALLINT CS_INT, "SalesStage" NVARCHAR(1) DEFAULT 'Y', "PurStage" NVARCHAR(1) DEFAULT 'Y', PRIMARY KEY ("Num")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "OOST_STEP" ON "TEST_AP"."OOST" ( "StepId" ASC )